from pathlib import Path
import base64,json
ROOT=Path(__file__).resolve().parent.parent;QA=ROOT/'qa/focus-connect';OUT=Path('/workspace/artifacts/Focus-skins-20261029.html')
screens={skin:{theme:{device:'data:image/png;base64,'+base64.b64encode((QA/f'{skin}-{theme}-{device}.png').read_bytes()).decode() for device in ['desktop','phone','tablet']} for theme in ['dark','light']} for skin in ['chrome','garnet']}
markup='''<!doctype html><html lang="ja"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Focus — 追加スキン</title><style>:root{color-scheme:dark}*{box-sizing:border-box}body{background:#0d1012;color:#e8ecea;font:15px/1.7 system-ui;margin:0}main{max-width:1180px;margin:auto;padding:32px 22px 60px}h1{font-size:26px;letter-spacing:-.03em;margin-bottom:0}p{color:#aab6b2;max-width:850px}.options{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0}button{background:#191f22;color:#dce5e0;border:1px solid #3a4642;border-radius:9px;font:inherit;padding:9px 17px;min-height:42px;cursor:pointer}button[aria-pressed=true]{background:#b7ccbf;color:#19271f;border-color:transparent}button:focus-visible{outline:2px solid #b7ccbf;outline-offset:3px}figure{margin:24px 0;text-align:center}img{display:block;margin:auto;width:100%;border:1px solid #3a4642;border-radius:14px}figure.phone img{max-width:390px}figure.tablet img{max-width:834px}.note{font-size:12px}.mark{font-size:12px;color:#b7ccbf}figcaption{color:#9ca9a3;margin:15px}.foot{border-top:1px solid #2c3632;padding-top:20px;margin-top:28px}</style><main><h1>Focus</h1><span class="mark">追加スキン · Chrome / Garnet</span><p>設定 → 表示 → スキンから選べます。Graphite・Glassはそのまま残り、初期表示は変更しません。ロゴは同心円です。画面は架空データによる実際のアプリのスクリーンショットです。</p><div class="options"><button data-skin="chrome" aria-pressed="true">Chrome</button><button data-skin="garnet" aria-pressed="false">Garnet</button></div><div class="options"><button data-device="desktop" aria-pressed="true">PC</button><button data-device="phone" aria-pressed="false">iPhone幅</button><button data-device="tablet" aria-pressed="false">iPad幅</button><button id="theme" aria-pressed="false">ライトで見る</button></div><figure><img alt="Focusのスキン表示・架空データ"><figcaption></figcaption></figure><p class="note">背景は静的なWebP画像2枚（合計約447KB）。配置や入力方式は変えず、連続する背景アニメーション・外部画像読み込みを使いません。スキンとテーマは端末ごとの設定です。</p><p class="note foot">PC・スマートフォン・タブレット相当の3つの独立保存領域で、計測の引継ぎ・1件だけの完了記録・オフライン追記の統合を検証。文字のコントラストとレイアウトを確認しました。物理Windows・iPhone・iPad、実Tailscale接続は未確認です。</p></main><script>const screens=SCREENS;let skin='chrome',device='desktop',theme='dark';function draw(){document.querySelector('img').src=screens[skin][theme][device];document.querySelector('figure').className=device;document.querySelector('figcaption').textContent=(skin==='chrome'?'Chrome · 銀／黒の金属と版画':'Garnet · 暗赤の装飾')+' / '+(theme==='dark'?'ダーク':'ライト');for(const b of document.querySelectorAll('[data-skin]'))b.setAttribute('aria-pressed',b.dataset.skin===skin);for(const b of document.querySelectorAll('[data-device]'))b.setAttribute('aria-pressed',b.dataset.device===device);document.querySelector('#theme').setAttribute('aria-pressed',theme==='light');document.querySelector('#theme').textContent=theme==='dark'?'ライトで見る':'ダークで見る';}document.onclick=e=>{if(e.target.dataset.skin)skin=e.target.dataset.skin;else if(e.target.dataset.device)device=e.target.dataset.device;else if(e.target.id==='theme')theme=theme==='dark'?'light':'dark';else return;draw();};draw();</script></html>'''
OUT.write_text(markup.replace('SCREENS',json.dumps(screens)));print(json.dumps({'file':str(OUT),'bytes':OUT.stat().st_size}))
